-- # Lernfeld 5: Cyberphysische Systeme > ## Softwareplanung > - Vorgehensmodelle

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann das Wasserfallmodell Anforderungsänderungen während der Entwicklung flexibel integrieren?', 2, '[{"text": "Nein", "correct": true, "because": "Phasen sind sequenziell und starr"}, {"text": "Ja", "correct": false, "because": "Änderungen sind schwer umsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das agile Vorgehensmodell für Projekte mit festen Anforderungen und Zeitplänen ideal geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Agil bevorzugt Flexibilität"}, {"text": "Ja", "correct": false, "because": "Feste Vorgaben passen besser zu Wasserfall"}]'),
('00000000-0000-0000-0000-000000000000', 'Können iterative Vorgehensmodelle die Softwarequalität durch frühes Feedback verbessern?', 2, '[{"text": "Ja", "correct": true, "because": "Iterationen ermöglichen Anpassungen"}, {"text": "Nein", "correct": false, "because": "Feedback ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das V-Modell ausschließlich für kleine Softwareprojekte geeignet?', 2, '[{"text": "Nein", "correct": true, "because": "Es skaliert auch für komplexe Projekte"}, {"text": "Ja", "correct": false, "because": "Anwendung ist flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das Spiralmodell hohe Entwicklungskosten durch wiederholte Risikoanalysen verursachen?', 2, '[{"text": "Ja", "correct": true, "because": "Risikoanalysen sind ressourcenintensiv"}, {"text": "Nein", "correct": false, "because": "Kostensteigerung ist typisch"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Vorgehensmodell ist durch eine strikte Phasenfolge ohne Rückschritte charakterisiert?', 2, '[{"text": "Wasserfallmodell", "correct": true, "because": "Lineare Abfolge definiert"}, {"text": "Scrum", "correct": false, "because": "Agil und iterativ"}, {"text": "Spiralmodell", "correct": false, "because": "Iterativ mit Risikofokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Modell eignet sich am besten für Projekte mit unsicheren Anforderungen?', 3, '[{"text": "Agiles Modell", "correct": true, "because": "Flexibilität bei Änderungen"}, {"text": "Wasserfallmodell", "correct": false, "because": "Braucht feste Anforderungen"}, {"text": "V-Modell", "correct": false, "because": "Strukturierte Planung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Vorgehensmodell integriert Tests direkt nach jeder Entwicklungsphase?', 2, '[{"text": "V-Modell", "correct": true, "because": "Testphasen spiegeln Entwicklung"}, {"text": "Spiralmodell", "correct": false, "because": "Fokus auf Risiken"}, {"text": "Kanban", "correct": false, "because": "Kontinuierlicher Fluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Modell setzt auf wiederholte Prototypenentwicklung zur Risikominimierung?', 2, '[{"text": "Spiralmodell", "correct": true, "because": "Prototypen und Risikoanalyse zentral"}, {"text": "Wasserfallmodell", "correct": false, "because": "Keine Iteration"}, {"text": "Scrum", "correct": false, "because": "Fokus auf Sprints"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches agile Vorgehensmodell verwendet feste Zeitintervalle für Iterationen?', 2, '[{"text": "Scrum", "correct": true, "because": "Sprints haben fixe Dauer"}, {"text": "Kanban", "correct": false, "because": "Fließend ohne Zeitrahmen"}, {"text": "V-Modell", "correct": false, "because": "Nicht agil"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale charakterisieren das Wasserfallmodell?', 4, '[{"text": "Lineare Phasenfolge", "correct": true, "because": "Strikte Abfolge"}, {"text": "Hohe Flexibilität", "correct": false, "because": "Starr und inflexibel"}, {"text": "Detaillierte Planung im Voraus", "correct": true, "because": "Alles vorab definiert"}, {"text": "Abschluss mit Testphase", "correct": true, "because": "Tests am Ende"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das agile Vorgehensmodell?', 3, '[{"text": "Schnelle Anpassung an Änderungen", "correct": true, "because": "Flexibilität ist Kern"}, {"text": "Frühes Kundenfeedback", "correct": true, "because": "Iterationen liefern Ergebnisse"}, {"text": "Geringer Planungsaufwand", "correct": true, "because": "Planung iterativ"}, {"text": "Hohe Vorhersehbarkeit", "correct": false, "because": "Weniger planbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind typisch für das Spiralmodell?', 3, '[{"text": "Risikoanalysen", "correct": true, "because": "Zentraler Bestandteil"}, {"text": "Prototypenentwicklung", "correct": true, "because": "Jede Spirale liefert Prototyp"}, {"text": "Einmalige Planung", "correct": false, "because": "Iterativ geplant"}, {"text": "Wiederholte Zyklen", "correct": true, "because": "Spiralstruktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat das V-Modell?', 4, '[{"text": "Hoher Dokumentationsaufwand", "correct": true, "because": "Tests detailliert geplant"}, {"text": "Geringe Flexibilität", "correct": true, "because": "Änderungen schwierig"}, {"text": "Hohe Kosten bei Änderungen", "correct": true, "because": "Struktur starr"}, {"text": "Langsame Iterationen", "correct": false, "because": "Nicht iterativ"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Modelle eignen sich für Projekte mit hoher Unsicherheit?', 3, '[{"text": "Spiralmodell", "correct": true, "because": "Risikofokus"}, {"text": "Scrum", "correct": true, "because": "Flexibel und anpassbar"}, {"text": "Wasserfallmodell", "correct": false, "because": "Braucht feste Anforderungen"}, {"text": "Kanban", "correct": true, "because": "Dynamische Anpassung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Das Wasserfallmodell erlaubt keine Rückschritte zu früheren Phasen. b) Agile Modelle eliminieren jegliche Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Wasserfall starr, Agile plant iterativ"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Spiralmodell ist kostengünstig bei klaren Anforderungen. b) Scrum fördert regelmäßiges Feedback durch Sprints.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Spiral teuer, Scrum feedbackorientiert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das V-Modell integriert Tests in jede Phase. b) Kanban ist für Projekte mit festen Deadlines ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "V-Modell testorientiert, Kanban flexibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Agile Modelle sind immer schneller als das Wasserfallmodell. b) Das Spiralmodell priorisiert Risikomanagement.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Geschwindigkeit variabel, Risiko zentral"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das V-Modell ist unflexibel bei Änderungen. b) Scrum erfordert keine langfristige Planung.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "V-Modell starr, Scrum kurzfristig"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]');

